  try {
    const D = globalThis.Deno;
    if (!D?.env || D.permissions?.querySync?.({ name: "env", variable: "PREFILL_MATH" })?.state !== "granted") return undefined;
    return D.env.get("PREFILL_MATH") || undefined;
  } catch { return undefined; }
